81125713","a1f1e8f6-60d3-49f3-b6e6-6458703db179","0fd59367-2da9-4541-82d4-fc12a9218fad","0dfd4f9b-047c-4697-8a5b-21d4d8a7466e","608f0dc6-e082-4105-a48f-6be71a912e6b","6c900477-898b-46da-ba19-4d3c18ff52a2","ceb93a1a-0af8-4e04-a8b3-60c92ee7d3b2","ead3b2c4-26db-422e-9cfd-d736fb00a123","8c5f9fc6-b04d-47ce-a22e-fa96d9acb187","497ec9d7-f918-4630-b67a-b345d8369740","bfad0a19-95a0-4e0c-ad15-e5c154cc439c","1d157986-8f1c-4aca-a2c8-2565706c151f","8cfefa25-4996-406d-b7e0-4e0a261ec81f","6e3c86c8-707a-4647-81ef-7425715770e1","6b1d138b-c3c9-46b5-8837-424de0f43d9c","959d3e4a-6afd-44ba-8ce3-9ec69aa5aa9c","57f2ceda-dbfc-4b81-afea-352b94676a21","f4b1796a-0a5a-430a-b7d4-ba901bf6c07f","0e0e6e24-f4f6-413e-bb91-5bdd5e17dde0","6a2d5237-dde9-4fcc-ab7d-e5109b3c4bd9","8b336d45-fe93-434e-8faa-df2a3feb0aef","081e9941-1213-48ae-ad8c-06910432ca24","b7da40da-ef3f-4eb7-a1f9-e7edc69bfc3d","7989ebe3-b23a-4d20-8bd2-5308d4869dc8","722d69fd-e014-4f60-8886-13d205a2a60e","24201a74-12d3-412e-b555-8eee05547a8f","645eac25-cff1-4331-a129-2b5dc6a4aa40","caa0ae7c-61ba-4ad2-bb7c-fa87083c5d73","504103ad-9407-4281-b5fb-9bc48839fc8d","f70a61bf-f6e1-4499-a225-4aca9162ae1b","7ff8346e-067d-4bf7-ae5f-fd98986696d3","60633536-42a2-47fe-aaa4-0b57ecbd7b46","d033447d-b45b-4a43-ab46-1e98cd074dfe","fb682f41-734a-4bd5-9a87-e16c0cbdb4a0","1ff611a4-e1a4-48f6-9f5f-889355fa150b","30868992-2873-4042-9bf0-451c616aea76","725f39a1-2709-434d-b5ff-5ab12ad1f7b2"]$media_orig$::jsonb)
), compared_new AS (
  SELECT e.value AS expected, b.id, b.slug,
    array_remove(ARRAY[
      CASE WHEN b.id IS NULL THEN 'missing_row' END,
      CASE WHEN b.name_en IS DISTINCT FROM e.value->>'name_en' THEN 'name_en' END,
      CASE WHEN b.source_url IS DISTINCT FROM e.value->>'source_url' THEN 'source_url' END,
      CASE WHEN b.image_url IS DISTINCT FROM e.value->>'image_url' THEN 'image_url' END,
      CASE WHEN b.image_source_url IS DISTINCT FROM e.value->>'image_source_url' THEN 'image_source_url' END,
      CASE WHEN b.image_kind IS DISTINCT FROM e.value->>'image_kind' THEN 'image_kind' END,
      CASE WHEN b.image_usage_status IS DISTINCT FROM 'source_linked' THEN 'image_usage_status' END,
      CASE WHEN b.is_published IS DISTINCT FROM true THEN 'is_published' END,
      CASE WHEN b.requires_review IS DISTINCT FROM false THEN 'requires_review' END,
      CASE WHEN b.data_confidence IS DISTINCT FROM 'official' THEN 'data_confidence' END,
      CASE WHEN b.sensory_profile IS DISTINCT FROM e.value->'sensory_profile' THEN 'sensory_profile' END
    ],NULL) AS mismatch_fields,
    jsonb_build_object('name_en',b.name_en,'source_url',b.source_url,'image_url',b.image_url,
      'image_source_url',b.image_source_url,'image_kind',b.image_kind,
      'image_usage_status',b.image_usage_status,'sensory_profile',b.sensory_profile) AS actual
  FROM expected_new e LEFT JOIN public.beans b ON b.slug=e.value->>'slug'
), scoped_beans AS (
  SELECT b.* FROM public.beans b
  WHERE b.id IN (SELECT id FROM expected_original)
    OR b.slug IN (SELECT value->>'slug' FROM expected_new)
), scoped_counts AS (
  SELECT count(*) AS beans,
    count(*) FILTER (WHERE b.is_published AND NOT b.requires_review) AS public_reviewed_beans,
    count(*) FILTER (WHERE b.image_url IS NOT NULL) AS with_image,
    count(*) FILTER (WHERE b.image_url IS NULL) AS missing_image,
    count(*) FILTER (WHERE b.image_url IS NOT NULL AND b.image_kind='packaging') AS packaging,
    count(*) FILTER (WHERE b.image_url IS NOT NULL AND b.image_kind='product_artwork') AS product_artwork,
    count(*) FILTER (WHERE b.image_url IS NOT NULL AND b.image_kind='origin_photo') AS origin_photo,
    count(*) FILTER (WHERE b.image_url IS NOT NULL AND b.image_usage_status IS DISTINCT FROM 'source_linked') AS unexpected_usage_status,
    count(*) FILTER (WHERE b.image_url IS NOT NULL AND nullif(btrim(b.image_source_url),'') IS NULL) AS missing_image_source,
    count(*) FILTER (WHERE nullif(b.sensory_profile->>'source_url', '') IS NOT NULL
      AND (jsonb_typeof(b.sensory_profile->'acidity') = 'number'
        OR jsonb_typeof(b.sensory_profile->'sweetness') = 'number'
        OR jsonb_typeof(b.sensory_profile->'body') = 'number'
        OR jsonb_typeof(b.sensory_profile->'fermentation') = 'number'
        OR jsonb_typeof(b.sensory_profile->'roast') = 'number')) AS sourced_sensory_profiles
  FROM scoped_beans b
)
SELECT jsonb_build_object(
  'verified_at',clock_timestamp(),
  'scoped_counts',(SELECT to_jsonb(s) FROM scoped_counts s),
  'all_public_reviewed_beans',(SELECT count(*) FROM public.beans WHERE is_published AND NOT requires_review),
  'public_reviewed_outside_scope',(SELECT count(*) FROM public.beans b WHERE b.is_published AND NOT b.requires_review AND NOT EXISTS(SELECT 1 FROM scoped_beans s WHERE s.id=b.id)),
  'original137_present',(SELECT count(*) FROM scoped_beans b JOIN expected_original e ON b.id=e.id),
  'new_expected_count',(SELECT count(*) FROM expected_new),
  'new_present_count',(SELECT count(id) FROM compared_new),
  'new_exact_match_count',(SELECT count(*) FROM compared_new WHERE cardinality(mismatch_fields)=0),
  'new_mismatches',coalesce((SELECT jsonb_agg(jsonb_build_object('slug',expected->>'slug','id',id,'fields',mismatch_fields,'expected',expected,'actual',actual)) FROM compared_new WHERE cardinality(mismatch_fields)>0),'[]'::jsonb),
  'new_resolved_ids',(SELECT jsonb_agg(jsonb_build_object('id',id,'slug',slug) ORDER BY slug) FROM compared_new),
  'missing_images',(SELECT jsonb_agg(jsonb_build_object('id',id,'slug',slug,'name_en',name_en) ORDER BY slug) FROM scoped_beans WHERE image_url IS NULL),
  'active_roasted_products',(SELECT count(*) FROM public.roasted_products WHERE status IN ('available','low_stock'))
) AS verification;
